# See possible rule: topmost color precedence matches exactly all demos?
A=['055550','550555','550500'];B=['004000','404440','400000'];C=['202202','200002','000200'];D=['080800','080000','080800'];O=['255552','554555','550500']
for priority in [(A,B,C,D),(A,C,B,D),(A,B,D,C),(B,A,C,D)]:
 matches=[]
 for r in range(3):
  for c in range(6):
   v=next((x[r][c] for x in priority if x[r][c]!='0'),'0')
   if v!=O[r][c]:matches.append((r,c,v,O[r][c]))
 print(len(matches),matches[:6])
