python3 - <<'PY'
A=['055550','550555','550500'];B=['004000','404440','400000'];C=['202202','200002','000200'];D=['080800','080000','080800'];O=['255552','554555','550500']
for label, fn in [('presence',lambda vals: next((x for x in vals if x!='0'),'0')),
 ('xor',lambda vals: next((x for x in vals if vals.count(x)==1 and x!='0'),'0')),
 ('majority',lambda vals: max(set(vals), key=vals.count))]:
 m=[]
 for r in range(3):
  for c in range(6):
   v=fn([A[r][c],B[r][c],C[r][c],D[r][c]])
   if v!=O[r][c]:m.append((r,c,v,O[r][c]))
 print(label,len(m),m)
